mapper.select:
/* Attd05Mapper.selectUserList */ WITH RECURSIVE node_tree AS ( /* 로그인 사용자의 node 부터 시작 */ SELECT N.CMPNY_CD , N.SITE_CD , N.NODE_CD , N.NODE_NM FROM TB_SITE_NODE N WHERE N.CMPNY_CD = #{gvCmpnyCd} AND N.SITE_CD = #{siteCd} AND N.NODE_CD = #{nodeCd}
UNION ALL
/* 하위 노드 무한 확장 */ SELECT C.CMPNY_CD , C.SITE_CD , C.NODE_CD , C.NODE_NM FROM TB_SITE_NODE C INNER JOIN node_tree P ON C.CMPNY_CD = P.CMPNY_CD AND C.SITE_CD = P.SITE_CD AND C.PARENT_NODE_CD = P.NODE_CD )
SELECT '' AS chk , A.CMPNY_CD AS cmpnyCd , A.USER_CD AS userCd , A.USER_ID AS userId , A.USER_NM AS userNm , A.SITE_CD AS siteCd , A.NODE_CD AS nodeCd , B.NODE_NM AS nodeNm , '' AS shiftTeam , A.MBL_NO_ENC AS mblNo FROM TB_USER A INNER JOIN node_tree B ON ( A.CMPNY_CD = B.CMPNY_CD AND A.SITE_CD = B.SITE_CD AND A.NODE_CD = B.NODE_CD ) WHERE A.ACCOUNT_STATUS != '03'
AND A.USER_NM LIKE CONCAT('%', #{userNm}, '%')
AND A.NODE_CD = #{nodeCd}

    /* Attd05Mapper.selectSchedList */
    SELECT 
		A.CMPNY_CD 			AS cmpnyCd
	    , A.SITE_CD			AS siteCd
	    , A.USER_CD 		AS userCd
	    , A.WORK_YMD		AS wrkYmd
	    , A.WORK_PLAN_CD	AS workPlanCd
	FROM TB_USER_WORK_PLAN A
	WHERE A.CMPNY_CD = #{gvCmpnyCd}
	  AND A.SITE_CD = #{siteCd}

/* Attd05Mapper.selectSchTypeUseYnList */ /* 근무타입(SCH_CD) effective-dating 검증용 버전 목록. TB_SCH_MGMT(현재본) 과 TB_SCH_MGMT_HIST(이력본)를 UNION 으로 합쳐 동일 SCH_CD + APPLY_DATE 가 중복되면 HIST_IDX 최댓값 1건만 채택한다. attd07 과 달리 USE_YN='N' 버전도 차단 근거로 살려야 하므로 USE_YN 필터를 걸지 않고 USE_YN 을 컬럼으로 SELECT 해 판정에 사용한다. */ SELECT E.SCH_CD AS schCd , E.APPLY_DATE AS applyDate , E.USE_YN AS useYn FROM ( /* 현재본 (HIST_IDX 를 최댓값으로 두어 동일 APPLY_DATE 중복 시 현재본 우선) */ SELECT M.CMPNY_CD , M.SITE_CD , M.SCH_CD , M.APPLY_DATE , M.USE_YN , 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M WHERE M.CMPNY_CD = #{gvCmpnyCd} AND M.SITE_CD = #{siteCd}
UNION ALL
/* 이력본 */ SELECT H.CMPNY_CD , H.SITE_CD , H.SCH_CD , H.APPLY_DATE , H.USE_YN , H.HIST_IDX FROM TB_SCH_MGMT_HIST H WHERE H.CMPNY_CD = #{gvCmpnyCd} AND H.SITE_CD = #{siteCd} ) E /* 동일 SCH_CD + APPLY_DATE 그룹에서 HIST_IDX 최댓값 행만 채택 */ WHERE E.HIST_IDX = ( SELECT MAX(E2.HIST_IDX) FROM ( SELECT M2.CMPNY_CD, M2.SITE_CD, M2.SCH_CD, M2.APPLY_DATE, 2147483647 AS HIST_IDX FROM TB_SCH_MGMT M2 WHERE M2.CMPNY_CD = #{gvCmpnyCd} AND M2.SITE_CD = #{siteCd} UNION ALL SELECT H2.CMPNY_CD, H2.SITE_CD, H2.SCH_CD, H2.APPLY_DATE, H2.HIST_IDX FROM TB_SCH_MGMT_HIST H2 WHERE H2.CMPNY_CD = #{gvCmpnyCd} AND H2.SITE_CD = #{siteCd} ) E2 WHERE E2.CMPNY_CD = E.CMPNY_CD AND E2.SITE_CD = E.SITE_CD AND E2.SCH_CD = E.SCH_CD AND E2.APPLY_DATE = E.APPLY_DATE ) ORDER BY E.SCH_CD, E.APPLY_DATE

mapper.update:
    /* Attd05Mapper.saveUserWorkPlans */
	INSERT INTO TB_USER_WORK_PLAN (
	    CMPNY_CD
	    , SITE_CD
	    , USER_CD
	    , WORK_YMD
	    , WORK_PLAN_CD
	    , INSERT_NO
	    , INSERT_DATE
	    , UPDATE_NO
	    , UPDATE_DATE
	) VALUES (
	    #{gvCmpnyCd}
	    , #{siteCd}
	    , #{userCd}
	    , #{workYmd}
	    , #{workPlanCd}
	    , #{gvUserCd}
	    , NOW()
	    , #{gvUserCd}
	    , NOW()
	) AS NEW
	ON DUPLICATE KEY UPDATE
		WORK_PLAN_CD	= NEW.WORK_PLAN_CD
	    , UPDATE_NO		= NEW.UPDATE_NO
	    , UPDATE_DATE	= NOW()

mapper.delete:
/* Attd05Mapper.deleteUserWorkPlans */
DELETE FROM TB_USER_WORK_PLAN
WHERE CMPNY_CD = #{gvCmpnyCd}
  AND SITE_CD = #{siteCd}
  AND USER_CD = #{userCd}
  AND WORK_YMD LIKE CONCAT(replace(#{workYm},'-', ''), '%')
